script:
var INITIAL = {{value}};
var WRITES = {{writes}};

var slotsGroup = document.getElementById('slots');
var caption = document.getElementById('caption');
var status = document.getElementById('status');

// 两个变量盒子：age 与 name（演示「不同名字装不同的东西」）
var BOXES = [
  { name: 'age', x: 40, color: '#2f6fd0' },
  { name: 'name', x: 250, color: '#1f9d63' }
];

var drawn = [];
for (var b = 0; b < BOXES.length; b += 1) {
  var box = BOXES[b];
  var rect = Sandbox.svgEl('rect');
  rect.setAttribute('x', String(box.x));
  rect.setAttribute('y', '46');
  rect.setAttribute('width', '170');
  rect.setAttribute('height', '110');
  rect.setAttribute('rx', '12');
  rect.setAttribute('fill', '#ffffff');
  rect.setAttribute('stroke', box.color);
  rect.setAttribute('stroke-width', '2');
  slotsGroup.appendChild(rect);

  // 名字标签（像贴在盒子外面的名牌）
  var tag = Sandbox.svgEl('text');
  tag.setAttribute('x', String(box.x + 12));
  tag.setAttribute('y', '32');
  tag.setAttribute('style', 'font-family:Consolas,Menlo,monospace;font-size:13px;font-weight:650;fill:' + box.color);
  tag.textContent = box.name;
  slotsGroup.appendChild(tag);

  var valueText = Sandbox.svgEl('text');
  valueText.setAttribute('x', String(box.x + 85));
  valueText.setAttribute('y', '112');
  valueText.setAttribute('text-anchor', 'middle');
  valueText.setAttribute('style', 'font-family:Consolas,Menlo,monospace;font-size:28px;font-weight:650;fill:#12233b');
  valueText.textContent = '—';
  slotsGroup.appendChild(valueText);

  drawn.push({ rect: rect, valueText: valueText, name: box.name, color: box.color });
}

var ageBox = drawn[0];
var nameBox = drawn[1];
var ageValue = INITIAL;
var writeIndex = 0;

function setValue(box, text) {
  box.valueText.textContent = text;
  anime({ targets: box.valueText, opacity: [0, 1], scale: [0.7, 1], duration: 300, easing: 'easeOutBack' });
  anime({ targets: box.rect, strokeWidth: [4, 2], duration: 380 });
}

function nextWrite() {
  // 每次写入都换一个值：体现「变量名不变，装的值会变」
  writeIndex += 1;
  ageValue += 1;
  return ageValue;
}

Sandbox.play(function () {
  writeIndex = 0;
  ageValue = INITIAL;
  ageBox.valueText.textContent = '—';
  nameBox.valueText.textContent = '—';

  var steps = [];

  steps.push({
    targets: ageBox.rect,
    duration: 260,
    begin: function () {
      caption.textContent = '写 age = ' + INITIAL + '：Python 先算右边，把结果放进名叫 age 的盒子。';
      status.textContent = 'age = ' + INITIAL;
    },
    complete: function () {
      setValue(ageBox, String(INITIAL));
    }
  });

  steps.push({
    targets: nameBox.rect,
    duration: 260,
    begin: function () {
      caption.textContent = '再写 name = "小明"：同一份程序里可以有多个变量，各自装各自的东西。';
    },
    complete: function () {
      setValue(nameBox, '"小明"');
    }
  });

  for (var w = 0; w < WRITES; w += 1) {
    steps.push({
      targets: ageBox.rect,
      duration: 320,
      begin: (function () {
        return function () {
          caption.textContent =
            '再来一次 age = age + 1：先取出盒子里现在的值，加上 1，再把新值放回去。' +
            '这就是「变量可以被重新赋值」。';
        };
      })(),
      complete: function () {
        setValue(ageBox, String(nextWrite()));
        status.textContent = 'age = ' + ageValue;
      }
    });
  }
  status.textContent = 'age = ' + ageValue;

  steps.push({
    targets: [ageBox.rect, nameBox.rect],
    strokeWidth: 3,
    duration: 300,
    direction: 'alternate',
    begin: function () {
      caption.textContent =
        '现在 age = ' + ageValue + '，name 还是 "小明"。' +
        '变量只是「名字」，装的东西可以换；名字起得清楚，程序才读得懂。';
    },
    complete: function () {
      Sandbox.progress(1);
    }
  });

  var timeline = anime.timeline({ autoplay: true, easing: 'easeInOutQuad' });
  for (var s = 0; s < steps.length; s += 1) timeline.add(steps[s]);
  timeline.play();

  var duration = timeline.duration || 4500;
  return {
    pause: function () { timeline.pause(); },
    play: function () { timeline.play(); },
    restart: function () { timeline.restart(); },
    finished: {
      then: function (resolve) {
        var elapsed = 0;
        var timer = setInterval(function () {
          elapsed += 100;
          if (timeline.completed || elapsed > duration + 800) {
            clearInterval(timer);
            resolve();
          }
          Sandbox.progress(Math.min(1, elapsed / duration));
        }, 100);
      }
    }
  };
});

Sandbox.ready({ template: 'python-variable', initial: INITIAL });
